{
  "root": "main_stack",
  "state": {
    "accommodationComparison": [
      {
        "Hotel": "Radisson Blu Kenilworth",
        "Nightly Rate": 280,
        "Total (5 Nights)": 1400,
        "Proximity": "0.1 miles",
        "Family Room": "Yes"
      },
      {
        "Hotel": "The Bloomsbury Hotel",
        "Nightly Rate": 350,
        "Total (5 Nights)": 1750,
        "Proximity": "0.2 miles",
        "Family Room": "Yes"
      },
      {
        "Hotel": "Premier Inn Holborn",
        "Nightly Rate": 190,
        "Total (5 Nights)": 950,
        "Proximity": "0.6 miles",
        "Family Room": "No"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_main",
        "radisson_card",
        "table_heading",
        "comparison_table",
        "email_heading",
        "email_preview_card",
        "actions_heading",
        "actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title_main": {
      "type": "Text",
      "props": {
        "text": "British Museum Area Stay Analysis",
        "variant": "h1"
      },
      "children": []
    },
    "radisson_card": {
      "type": "Card",
      "props": {},
      "children": [
        "radisson_heading_stack",
        "radisson_image",
        "radisson_text"
      ]
    },
    "radisson_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "radisson_icon",
        "radisson_heading_text"
      ]
    },
    "radisson_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg"
      },
      "children": []
    },
    "radisson_heading_text": {
      "type": "Text",
      "props": {
        "text": "Radisson Blu Edwardian Kenilworth Selection",
        "variant": "h2"
      },
      "children": []
    },
    "radisson_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/The_British_Museum_from_the_northeast_2.JPG/1200px-The_British_Museum_from_the_northeast_2.JPG",
        "fit": "cover"
      },
      "children": []
    },
    "radisson_text": {
      "type": "Text",
      "props": {
        "text": "The Radisson Blu Edwardian Kenilworth is the only option that meets all your criteria. It provides a confirmed Family Room, falls exactly within your $1,500 budget, and is located just 0.1 miles from the British Museum.",
        "variant": "body"
      },
      "children": []
    },
    "table_heading": {
      "type": "Text",
      "props": {
        "text": "Accommodation Comparison Table",
        "variant": "h2"
      },
      "children": []
    },
    "comparison_table": {
      "type": "Table",
      "props": {
        "statePath": "/accommodationComparison",
        "columns": [
          {
            "key": "Hotel",
            "label": "Hotel"
          },
          {
            "key": "Nightly Rate",
            "label": "Nightly Rate"
          },
          {
            "key": "Total (5 Nights)",
            "label": "Total (5 Nights)"
          },
          {
            "key": "Proximity",
            "label": "Proximity"
          },
          {
            "key": "Family Room",
            "label": "Family Room"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "Hotel",
        "highlightColumns": [
          "Total (5 Nights)",
          "Proximity"
        ],
        "numericColumns": [
          "Nightly Rate",
          "Total (5 Nights)"
        ]
      },
      "children": []
    },
    "email_heading": {
      "type": "Text",
      "props": {
        "text": "Sample Reservation Email",
        "variant": "h3"
      },
      "children": []
    },
    "email_preview_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email_preview_stack"
      ]
    },
    "email_preview_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "email_subject_text",
        "email_body_line1",
        "email_body_line2",
        "email_body_line3",
        "email_body_line4"
      ]
    },
    "email_subject_text": {
      "type": "Text",
      "props": {
        "text": "Subject: Reservation Request - [Your Name] - May 10-15, 2025",
        "variant": "h4"
      },
      "children": []
    },
    "email_body_line1": {
      "type": "Text",
      "props": {
        "text": "Dear Reservations Team,",
        "variant": "body"
      },
      "children": []
    },
    "email_body_line2": {
      "type": "Text",
      "props": {
        "text": "I would like to book a Family Room for 2 adults and 1 child (8 years old) for 5 nights, checking in on May 10 and checking out on May 15, 2025. Please confirm that free Wi-Fi is included.",
        "variant": "body"
      },
      "children": []
    },
    "email_body_line3": {
      "type": "Text",
      "props": {
        "text": "Best regards,",
        "variant": "body"
      },
      "children": []
    },
    "email_body_line4": {
      "type": "Text",
      "props": {
        "text": "[Your Name].",
        "variant": "body"
      },
      "children": []
    },
    "actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_book_radisson",
        "button_museum_info"
      ]
    },
    "button_book_radisson": {
      "type": "Button",
      "props": {
        "label": "Book Radisson Blu"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.radissonhotels.com"
          }
        }
      },
      "children": []
    },
    "button_museum_info": {
      "type": "Button",
      "props": {
        "label": "British Museum Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.britishmuseum.org"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_radisson_source",
        "button_museum_source"
      ]
    },
    "button_radisson_source": {
      "type": "Button",
      "props": {
        "label": "Radisson Hotels"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.radissonhotels.com"
          }
        }
      },
      "children": []
    },
    "button_museum_source": {
      "type": "Button",
      "props": {
        "label": "British Museum Official"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.britishmuseum.org"
          }
        }
      },
      "children": []
    }
  }
}
